import uuid

import pytest
import stripe

from app.src.stripe_services.customers.customer_service import CustomerService


def test_retrieve_customer():
    service = CustomerService()

    # First, create a customer
    customer = service.create_customer(
        name="Retrieve Test Customer",
        email=f"retrieve.{uuid.uuid4().hex[:8]}@example.com"
    )

    # Get the customer ID generated by Stripe
    customer_id = customer.id

    # Retrieve the same customer
    retrieved_customer = service.retrieve_customer(customer_id)

    # Verify the returned information
    assert retrieved_customer.id == customer_id
    assert retrieved_customer.name == "Retrieve Test Customer"
    assert retrieved_customer.email == customer.email

    print(f"\nRetrieved customer: {retrieved_customer.id}")


def test_retrieve_invalid_customer():
    service = CustomerService()

    with pytest.raises(
            stripe.InvalidRequestError,
            match="No such customer"
    ):
        service.retrieve_customer("cus_invalid123")


def test_update_customer():
    service = CustomerService()

    # Create a customer first
    customer = service.create_customer(
        name="John Smith",
        email=f"john.{uuid.uuid4().hex[:8]}@example.com"
    )

    # Update the customer's information
    updated_customer = service.update_customer(
        customer_id=customer.id,
        name="John Smith Updated",
        email=f"updated.{uuid.uuid4().hex[:8]}@example.com"
    )

    # Verify the updated information
    assert updated_customer.id == customer.id
    assert updated_customer.name == "John Smith Updated"
    assert updated_customer.email.startswith("updated.")

    print(f"\nUpdated customer: {updated_customer.id}")


def test_list_customers():
    service = CustomerService()

    # Create a customer so we have a known record to find
    new_customer = service.create_customer(
        name="List Test Customer",
        email=f"list.{uuid.uuid4().hex[:8]}@example.com"
    )

    # Retrieve the customer list
    customer_list = service.list_customers(limit=10)

    # Verify the response
    assert customer_list.object == "list"
    assert len(customer_list.data) <= 10

    customer_ids = [customer.id for customer in customer_list.data]
    assert new_customer.id in customer_ids

    print(f"\nCustomers returned: {len(customer_list.data)}")
    print(f"New customer found: {new_customer.id}")


def test_list_customers_pagination():
    service = CustomerService()

    # Create 3 customers for this test
    created_customers = []

    for number in range(3):
        customer = service.create_customer(
            name=f"Pagination Customer {number}",
            email=f"pagination.{uuid.uuid4().hex[:8]}@example.com"
        )
        created_customers.append(customer)

    # Get the first page
    first_page = service.list_customers(limit=2)

    assert len(first_page.data) == 2
    assert first_page.has_more is True

    # Get the second page using the last ID from page one
    last_customer_id = first_page.data[-1].id

    second_page = service.list_customers(
        limit=2,
        starting_after=last_customer_id
    )

    assert len(second_page.data) >= 1

    first_page_ids = [customer.id for customer in first_page.data]
    second_page_ids = [customer.id for customer in second_page.data]

    # Make sure the pages don't contain duplicate customers
    assert not set(first_page_ids).intersection(second_page_ids)

    print(f"\nFirst page: {first_page_ids}")
    print(f"Second page: {second_page_ids}")


def test_delete_customer():
    service = CustomerService()

    # Create a customer specifically for deletion
    customer = service.create_customer(
        name="Delete Test Customer",
        email=f"delete.{uuid.uuid4().hex[:8]}@example.com"
    )

    # Delete the customer
    deleted_customer = service.delete_customer(customer.id)

    # Verify deletion
    assert deleted_customer.id == customer.id
    assert deleted_customer.deleted is True

    print(f"\nDeleted customer: {deleted_customer.id}")


def test_create_customer_empty_name():
    service = CustomerService()

    with pytest.raises(
            ValueError,
            match="Customer name cannot be empty"
    ):
        service.create_customer(
            name="   ",
            email="test@example.com"
        )


