def test_create_customer_strips_whitespace():
    service = CustomerService()

    customer = service.create_customer(
        name="  John Smith  ",
        email=f"  john.{uuid.uuid4().hex[:8]}@example.com  "
    )

    assert customer.name == "John Smith"
    assert customer.email.startswith("john.")
    assert customer.email.endswith("@example.com")

    print(f"\nCreated customer: {customer.id}")


