def test_stripe_authentication_error():
    invalid_client = stripe.StripeClient(
        "sk_test_invalid_key_12345"
    )

    with pytest.raises(stripe.AuthenticationError):
        invalid_client.v1.customers.list(
            params={"limit": 1}
        )


def test_create_customer_with_idempotency_key():
    service = CustomerService()

    idempotency_key = f"customer-{uuid.uuid4().hex}"

    first_customer = service.create_customer(
        name="Idempotency Test Customer",
        email=f"idempotency.{uuid.uuid4().hex[:8]}@example.com",
        idempotency_key=idempotency_key
    )

    second_customer = service.create_customer(
        name="Idempotency Test Customer",
        email=first_customer.email,
        idempotency_key=idempotency_key
    )

    assert first_customer.id == second_customer.id

    print(f"\nCustomer ID: {first_customer.id}")
    print("Idempotency verification successful")
